int pqcp_channel_fault_policy_lookup(
	enum pqcp_channel_fault_condition condition,
	enum pqcp_channel_control_kind control,
	struct pqcp_channel_fault_policy_decision *decision)
{
	if (condition < PQCP_CHANNEL_FAULT_NONE ||
	    condition >= PQCP_CHANNEL_FAULT_CONDITION_COUNT ||
	    control < PQCP_CHANNEL_CONTROL_NONE ||
	    control >= PQCP_CHANNEL_CONTROL_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = channel_fault_catalog[condition][control];
	return 0;
}

int pqcp_channel_fault_policy_catalog_audit(void)
{
	for (size_t condition = 0U;
	     condition < PQCP_CHANNEL_FAULT_CONDITION_COUNT;
	     ++condition) {
		for (size_t control = 0U;
		     control < PQCP_CHANNEL_POLICY_CONTROL_COUNT;
		     ++control) {
			const struct pqcp_channel_fault_policy_decision
				*entry =
					&channel_fault_catalog
						[condition][control];

			if ((size_t)entry->condition != condition ||
			    (size_t)entry->control != control ||
			    entry->directive >
				PQCP_CHANNEL_FAULT_TERMINATE_CHANNEL ||
			    entry->next_state <
				PQCP_CHANNEL_POLICY_NEW ||
			    entry->next_state >
				PQCP_CHANNEL_POLICY_TERMINATED ||
			    entry->reason_mask == 0U) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}
